ALTER TABLE public.tsla_withdrawals ADD COLUMN IF NOT EXISTS fee_tsla numeric NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.tesla_paid_withdrawal(p_user_id bigint,p_amount numeric,p_address text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.tsla_tg_users; w uuid; BEGIN SELECT * INTO u FROM public.tsla_tg_users WHERE id=p_user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF; IF p_amount IS NULL OR p_amount::text IN ('NaN','Infinity','-Infinity') OR p_amount<100 OR p_amount>1000000000000 THEN RAISE EXCEPTION 'Invalid withdrawal amount'; END IF; IF NOT coalesce(u.wallet_verified,false) OR u.wallet_address IS DISTINCT FROM p_address THEN RAISE EXCEPTION 'Verify wallet ownership first'; END IF; IF EXISTS(SELECT 1 FROM public.tsla_withdrawals WHERE user_id=p_user_id AND status IN ('pending','submitted')) THEN RAISE EXCEPTION 'Earlier withdrawal still pending'; END IF; IF u.balance<p_amount+1 THEN RAISE EXCEPTION 'Not enough TSLA including fee'; END IF; UPDATE public.tsla_tg_users SET balance=balance-p_amount-1 WHERE id=p_user_id; INSERT INTO public.tsla_withdrawals(user_id,amount,to_address,fee_tsla,status) VALUES(p_user_id,p_amount,p_address,1,'pending') RETURNING id INTO w; RETURN w; END $$;
REVOKE ALL ON FUNCTION public.tesla_paid_withdrawal(bigint,numeric,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.tesla_paid_withdrawal(bigint,numeric,text) TO service_role;